import os, zipfile
needles=['LEFT(K','FIND(" ",K','Start finishing','End finishing','Start Time']
hits=[]
count=0
for root,dirs,files in os.walk('/tmp'):
    for f in files:
        if f.lower().endswith('.xlsx') and not f.startswith('~$'):
            p=os.path.join(root,f)
            try:
                z=zipfile.ZipFile(p)
                for n in z.namelist():
                    if 'sheet' in n.lower() and n.endswith('.xml'):
                        data=z.read(n).decode('utf-8','replace')
                        if any(nd in data for nd in needles):
                            hits.append((p,[nd for nd in needles if nd in data]))
                            break
            except Exception:
                pass
print('hits',len(hits))
for h in hits[:300]:
    print(h)
